# Strategy uses only observations and results from the current half.
# NumPy is already in the tournament base image. A stdlib path also works
# with just the participant requirements.txt on a local machine.
import random
import time
from itertools import combinations, permutations

from evaluator import get_table

try:
    import numpy as np
except ImportError:
    np = None

_HOLE_PAIRS = tuple(combinations(range(5), 2))
_BOARD_TRIPLES = {n: tuple(combinations(range(n), 3)) for n in (3, 4, 5)}
_CARD_BITS = tuple(1 << c for c in range(36))
_FIVE_SCORES = get_table()


def _build_fast_tables():
    """Immutable 18 MB pair/triple table; built before the thinking clock."""
    pairs = np.array(list(combinations(range(36), 2)), dtype=np.int32)
    pair_ids = np.zeros((36, 36), dtype=np.int32)
    for i, (a, b) in enumerate(pairs):
        pair_ids[a, b] = pair_ids[b, a] = i
    triple_ids = np.zeros((36, 36, 36), dtype=np.int32)
    for i, cards in enumerate(combinations(range(36), 3)):
        for a, b, c in permutations(cards):
            triple_ids[a, b, c] = i
    cards = np.array(list(combinations(range(36), 5)), dtype=np.int32)
    # Do not depend on the insertion order of the referee's score dictionary.
    masks = np.left_shift(np.uint64(1), cards.astype(np.uint64)).sum(axis=1)
    scores = np.fromiter((_FIVE_SCORES[int(m)] for m in masks), dtype=np.int32,
                         count=len(cards))
    lookup = np.zeros((630, 7140), dtype=np.int32)
    for i, j in _HOLE_PAIRS:
        k, l, m = (v for v in range(5) if v != i and v != j)
        lookup[pair_ids[cards[:, i], cards[:, j]],
               triple_ids[cards[:, k], cards[:, l], cards[:, m]]] = scores
    for array in (pairs, pair_ids, triple_ids, lookup):
        array.flags.writeable = False
    return pairs, pair_ids, triple_ids, lookup


if np is not None:
    _PAIRS, _PAIR_IDS, _TRIPLE_IDS, _LOOKUP = _build_fast_tables()
    _PI = np.array([p[0] for p in _HOLE_PAIRS])
    _PJ = np.array([p[1] for p in _HOLE_PAIRS])
    _BI = {n: np.array(t, dtype=np.int32).T for n, t in _BOARD_TRIPLES.items()}


def _batch_scores(holes, boards):
    """Exact PLO scores for arrays of holdings and 3, 4, or 5 board cards."""
    pairs = _PAIR_IDS[holes[:, _PI], holes[:, _PJ]]
    i, j, k = _BI[boards.shape[1]]
    triples = _TRIPLE_IDS[boards[:, i], boards[:, j], boards[:, k]]
    return _LOOKUP[pairs[:, :, None], triples[:, None, :]].max(axis=(1, 2))


def _sample_cards(rng, available, count, width):
    """Independent uniform ordered samples, without replacement in each row."""
    order = rng.random((count, len(available))).argsort(axis=1)[:, :width]
    return available[order]


def _pair_scores(board):
    triples = [_TRIPLE_IDS[a, b, c] for a, b, c in combinations(board, 3)]
    return _LOOKUP[:, triples].max(axis=1)


def _partial_score(hole, board):
    hm = [_CARD_BITS[a] | _CARD_BITS[b] for a, b in combinations(hole, 2)]
    bm = [_CARD_BITS[a] | _CARD_BITS[b] | _CARD_BITS[c]
          for a, b, c in combinations(board, 3)]
    return max(_FIVE_SCORES[h | b] for h in hm for b in bm)


